CREATE TABLE events (id BIGSERIAL PRIMARY KEY,title VARCHAR(255) NOT NULL,venue VARCHAR(255) NOT NULL,starts_at TIMESTAMPTZ NOT NULL,price NUMERIC(12,2) NOT NULL CHECK(price>0),capacity INTEGER NOT NULL CHECK(capacity>0),available_tickets INTEGER NOT NULL CHECK(available_tickets>=0),banner_url VARCHAR(2048),version BIGINT NOT NULL DEFAULT 0); CREATE INDEX idx_events_title ON events(title); CREATE INDEX idx_events_starts_at ON events(starts_at);
